patches.content:
// battery_trend: offer the module tile in edit mode whenever
// it is absent from the configured toggle list.
ButtonGroup {
    visible: !root.toggles.some(t => t && t.type === "battery_trend")
    spacing: root.spacing

    Repeater {
        model: ScriptModel {
            values: root.toggles.some(t => t && t.type === "battery_trend") ? [] : [{ type: "battery_trend", size: 1 }]
            objectProp: "type"
        }
        delegate: AndroidToggleDelegateChooser {
            startingIndex: -1
            editMode: root.editMode
            baseCellWidth: root.baseCellWidth
            baseCellHeight: root.baseCellHeight
            spacing: root.spacing
        }
    }
}
